package router

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/marinoscar/local-ai/agent/internal/catalog"
)

// RendererVersion is part of inputs_sha256, so a change to the rendering rules changes the hash
// even when the catalog does not.
const RendererVersion = 1

// headerPrefix starts the first line of the generated file, the one line that is excluded from
// every comparison (it carries the time and the agent version).
const headerPrefix = "; GENERATED by aiagent "

// Preset is one model's section of models.ini before it is rendered: the section name and the
// key/value pairs in table order (llama-router.md section 3.5.1), without load-on-startup, which
// Render adds to the default model's section.
type Preset struct {
	ID    string
	Pairs []Pair
	// Paths are the absolute files the section names, for the readability check (step 3).
	Paths []string
}

// Pair is one INI key and its value.
type Pair struct{ Key, Value string }

// PresetError is a catalog entry or path that cannot be rendered (LAI-LLM-007). It names the model
// and says what is wrong in one line; it never holds a file's contents.
type PresetError struct {
	Model  string
	Reason string
}

// Error implements error.
func (e *PresetError) Error() string { return "model " + e.Model + ": " + e.Reason }

func presetErr(id, format string, args ...any) *PresetError {
	return &PresetError{Model: id, Reason: fmt.Sprintf(format, args...)}
}

var (
	// sectionIDRe is what may be a section name; the catalog's id format is a subset of it.
	sectionIDRe = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)
	// extraKeyRe is what an extra_args flag may normalise to.
	extraKeyRe = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_-]*$`)
	// shardFirstRe matches the first shard of a multi-file GGUF.
	shardFirstRe = regexp.MustCompile(`-0*1-of-[0-9]+\.gguf$`)
)

// reservedKeys are keys an extra_args flag may never set: the router owns them, or the agent
// writes them from other catalog fields. Matching is on the normalised, lower-case key; a name
// ending in "-" is a prefix.
var reservedKeys = []string{
	"host", "port", "api-key", "api-key-", "m", "model", "model-", "models-", "alias", "hf", "hf-",
	"mmproj", "mmproj-", "load-on-startup", "stop-timeout", "tags", "version",
}

func reservedKey(k string) bool {
	k = strings.ToLower(k)
	for _, r := range reservedKeys {
		if strings.HasSuffix(r, "-") {
			if strings.HasPrefix(k, r) {
				return true
			}
		} else if k == r {
			return true
		}
	}
	return false
}

// CheckPath refuses a path that cannot be written into the INI as is (llama-router.md section
// 3.5.1): it must be absolute and contain no ';', '#', control character, or leading or trailing
// space. Values are never quoted, so these are the characters that would change the meaning.
func CheckPath(p string) error {
	switch {
	case p == "" || !strings.HasPrefix(p, "/"):
		return fmt.Errorf("the path is not absolute")
	case p != strings.TrimSpace(p):
		return fmt.Errorf("the path has a leading or trailing space")
	case strings.ContainsAny(p, ";#"):
		return fmt.Errorf("the path contains ';' or '#'")
	}
	for _, r := range p {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("the path contains a control character")
		}
	}
	return nil
}

// checkValue is CheckPath's rule for the free-text values of extra_args and aliases.
func checkValue(v string) error {
	if strings.ContainsAny(v, ";#") {
		return fmt.Errorf("contains ';' or '#'")
	}
	for _, r := range v {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("contains a control character")
		}
	}
	return nil
}

// filePath joins a catalog file name onto <root>/models/<id>. A name that is absolute or climbs
// out of the model directory is refused (the loader lints this too; a preset must never point
// outside the model's directory).
func filePath(root, id, name string) (string, error) {
	if name == "" || strings.HasPrefix(name, "/") {
		return "", fmt.Errorf("file name %q is not relative", name)
	}
	clean := path.Clean(name)
	if clean == ".." || strings.HasPrefix(clean, "../") || clean != name {
		return "", fmt.Errorf("file name %q is not a plain relative path", name)
	}
	return modelDir(root, id) + "/" + clean, nil
}

// pickFile returns the absolute path of the model's file of the given kind. One file of the kind
// is that file; several are the shards of one model, and the one whose name ends in
// -00001-of-NNNNN.gguf is the file the router is given.
func pickFile(m *catalog.Model, root, kind string) (string, error) {
	var names []string
	for _, f := range m.Files {
		if f.Kind == kind {
			names = append(names, f.Name)
		}
	}
	var name string
	switch len(names) {
	case 0:
		return "", fmt.Errorf("no files entry of kind %s", kind)
	case 1:
		name = names[0]
	default:
		var first []string
		for _, n := range names {
			if shardFirstRe.MatchString(n) {
				first = append(first, n)
			}
		}
		if len(first) != 1 {
			return "", fmt.Errorf("%d files of kind %s and no single first shard (-00001-of-NNNNN)", len(names), kind)
		}
		name = first[0]
	}
	p, err := filePath(root, m.ID, name)
	if err != nil {
		return "", err
	}
	if err := CheckPath(p); err != nil {
		return "", err
	}
	return p, nil
}

func intOrAll(v catalog.IntOrAll) (string, bool) {
	switch {
	case !v.Set:
		return "", false
	case v.All:
		return "all", true
	}
	return strconv.Itoa(v.N), true
}

// BuildPreset renders one model's section pairs from its catalog entry (llama-router.md section
// 3.5.1), with root the chosen content root and aliases the model's routing aliases (already
// checked for conflicts). The keys come out in table order and nothing is quoted. Fields the
// table does not map (requirements, client_hints, summary, env) are not rendered. An entry that
// cannot be rendered returns a *PresetError.
func BuildPreset(m *catalog.Model, root string, aliases []string) (Preset, error) {
	if m == nil {
		return Preset{}, presetErr("", "no catalog entry")
	}
	id := m.ID
	if !sectionIDRe.MatchString(id) {
		return Preset{}, presetErr(id, "the id cannot be a section name")
	}
	l := m.Llama
	if l == nil {
		return Preset{}, presetErr(id, "the entry has no llama block")
	}
	if l.Ctx <= 0 {
		return Preset{}, presetErr(id, "llama.ctx must be a positive number")
	}
	p := Preset{ID: id}
	add := func(k, v string) { p.Pairs = append(p.Pairs, Pair{k, v}) }
	file := func(kind string) (string, error) {
		fp, err := pickFile(m, root, kind)
		if err != nil {
			return "", presetErr(id, "%v", err)
		}
		p.Paths = append(p.Paths, fp)
		return fp, nil
	}

	weights, err := file("weights")
	if err != nil {
		return Preset{}, err
	}
	add("model", weights)
	add("c", strconv.Itoa(l.Ctx))
	if v, ok := intOrAll(l.NGPULayers); ok {
		add("n-gpu-layers", v)
	}
	if l.FlashAttn != "" {
		if !oneOfStr(l.FlashAttn, "on", "off", "auto") {
			return Preset{}, presetErr(id, "llama.flash_attn %q is not on, off or auto", l.FlashAttn)
		}
		add("flash-attn", l.FlashAttn)
	}
	if l.Parallel > 0 {
		add("parallel", strconv.Itoa(l.Parallel))
	}
	if sp := l.Speculative; sp != nil && sp.Type != "" {
		if !oneOfStr(sp.Type, "draft-mtp", "draft") {
			return Preset{}, presetErr(id, "llama.speculative.type %q is not draft-mtp or draft", sp.Type)
		}
		add("spec-type", sp.Type)
		if sp.NMax > 0 {
			add("spec-draft-n-max", strconv.Itoa(sp.NMax))
		}
		if sp.DraftFileKind != "" {
			dp, err := file(sp.DraftFileKind)
			if err != nil {
				return Preset{}, err
			}
			add("model-draft", dp)
			if v, ok := intOrAll(sp.DraftNGL); ok {
				add("spec-draft-ngl", v)
			}
		}
	}
	if l.MmprojFileKind != "" {
		mp, err := file(l.MmprojFileKind)
		if err != nil {
			return Preset{}, err
		}
		add("mmproj", mp)
	}
	if l.ChatTemplate != "" {
		if l.ChatTemplate == "chat_template" { // the file kind
			tp, err := file("chat_template")
			if err != nil {
				return Preset{}, err
			}
			add("chat-template-file", tp)
		} else {
			if err := checkValue(l.ChatTemplate); err != nil || strings.TrimSpace(l.ChatTemplate) != l.ChatTemplate {
				return Preset{}, presetErr(id, "llama.chat_template is not a plain template name")
			}
			add("chat-template", l.ChatTemplate)
		}
	}
	extra, err := ParseExtraArgs(l.ExtraArgs)
	if err != nil {
		return Preset{}, presetErr(id, "llama.extra_args: %v", err)
	}
	have := map[string]bool{}
	for _, pr := range p.Pairs {
		have[pr.Key] = true
	}
	for _, pr := range extra {
		if have[pr.Key] {
			return Preset{}, presetErr(id, "llama.extra_args sets %q, which the catalog already sets with a field", pr.Key)
		}
		have[pr.Key] = true
		p.Pairs = append(p.Pairs, pr)
	}
	if len(m.Roles) > 0 {
		for _, r := range m.Roles {
			if r == "" || strings.ContainsAny(r, ",;# \t\r\n") {
				return Preset{}, presetErr(id, "role %q cannot be a tag", r)
			}
		}
		add("tags", strings.Join(m.Roles, ","))
	}
	if len(aliases) > 0 {
		add("alias", strings.Join(aliases, ","))
	}
	return p, nil
}

func oneOfStr(v string, set ...string) bool {
	for _, s := range set {
		if v == s {
			return true
		}
	}
	return false
}

// ParseExtraArgs turns catalog llama.extra_args into INI pairs (llama-router.md section 3.5.1):
// "--foo bar" and "--foo=bar" become foo = bar, "--foo" and "--no-foo" become foo = true and
// no-foo = true, "-x v" becomes x = v. A flag and its value may also be two list entries. The
// linter already refuses the arguments the router owns; they are refused here too (and so is any
// key that would collide with a preset field the agent writes itself).
func ParseExtraArgs(args []string) ([]Pair, error) {
	var out []Pair
	seen := map[string]bool{}
	open := false // the last pair is a flag without a value yet (a split-form value may follow)
	for _, raw := range args {
		a := strings.TrimSpace(raw)
		if a == "" {
			continue
		}
		if !strings.HasPrefix(a, "-") || (open && isNumber(a)) {
			if !open {
				return nil, fmt.Errorf("%q is a value without a flag", clip(a, 40))
			}
			if err := checkValue(a); err != nil {
				return nil, fmt.Errorf("the value of %q %v", out[len(out)-1].Key, err)
			}
			out[len(out)-1].Value = a
			open = false
			continue
		}
		flag, value := a, ""
		if i := strings.IndexAny(a, " \t="); i >= 0 {
			flag, value = a[:i], strings.TrimSpace(a[i+1:])
		}
		key := strings.TrimPrefix(strings.TrimPrefix(flag, "-"), "-")
		if strings.HasPrefix(flag, "---") || !extraKeyRe.MatchString(key) {
			return nil, fmt.Errorf("%q is not a flag", clip(flag, 40))
		}
		if reservedKey(key) {
			return nil, fmt.Errorf("%q is controlled by the router", flag)
		}
		if seen[key] {
			return nil, fmt.Errorf("%q is given twice", flag)
		}
		seen[key] = true
		open = value == ""
		if value == "" {
			value = "true"
		}
		if err := checkValue(value); err != nil {
			return nil, fmt.Errorf("the value of %q %v", flag, err)
		}
		out = append(out, Pair{key, value})
	}
	return out, nil
}

func isNumber(s string) bool {
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

// Header is the comment block that opens models.ini.
type Header struct {
	// AgentVersion and At fill the first line, which is excluded from comparisons.
	AgentVersion string
	At           time.Time
	Node         string
	Profile      string
	Catalog      string
	// InputsSHA256 is the hash of the canonical inputs (see InputsHash).
	InputsSHA256 string
}

// headerWord makes a header value safe for a comment line: anything outside letters, digits and
// . _ - : + becomes "_", and an empty value becomes "-".
func headerWord(s string) string {
	if s == "" {
		return "-"
	}
	var b strings.Builder
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '.', r == '_', r == '-', r == ':', r == '+':
			b.WriteRune(r)
		default:
			b.WriteByte('_')
		}
	}
	return b.String()
}

// Render writes models.ini (llama-router.md section 3.5.1): the header, the [*] defaults, then
// one section per preset sorted by id, keys in table order, values unquoted. defaultID names the
// model whose section gets load-on-startup = true ("" for none). The output depends only on the
// arguments, so identical inputs give identical bytes (the time is in the first line only).
func Render(h Header, presets []Preset, defaultID string) ([]byte, error) {
	sorted := append([]Preset(nil), presets...)
	sort.SliceStable(sorted, func(a, b int) bool { return sorted[a].ID < sorted[b].ID })
	for i := 1; i < len(sorted); i++ {
		if sorted[i].ID == sorted[i-1].ID {
			return nil, fmt.Errorf("router: duplicate preset %q", sorted[i].ID)
		}
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s%s at %s — DO NOT EDIT (changes are overwritten).\n", headerPrefix, headerWord(h.AgentVersion), h.At.UTC().Format("2006-01-02T15:04:05Z"))
	fmt.Fprintf(&b, "; node=%s profile=%s catalog=%s inputs_sha256=%s\n", headerWord(h.Node), headerWord(h.Profile), headerWord(h.Catalog), headerWord(h.InputsSHA256))
	b.WriteString("; Spec: docs/specs/llama-router.md §3.5\n")
	b.WriteString("version = 1\n\n[*]\nstop-timeout = 10\nload-on-startup = false\n")
	for _, p := range sorted {
		fmt.Fprintf(&b, "\n[%s]\n", p.ID)
		for _, pr := range p.Pairs {
			fmt.Fprintf(&b, "%s = %s\n", pr.Key, pr.Value)
		}
		if p.ID == defaultID {
			b.WriteString("load-on-startup = true\n")
		}
	}
	return b.Bytes(), nil
}

// StripHeaderLine returns the file without its first line when that line is the generated header
// line (time and agent version): the form two renderings are compared in (llama-router.md section
// 4.2 step 2). Anything else is returned unchanged.
func StripHeaderLine(b []byte) []byte {
	if !bytes.HasPrefix(b, []byte(headerPrefix)) {
		return b
	}
	if i := bytes.IndexByte(b, '\n'); i >= 0 {
		return b[i+1:]
	}
	return nil
}

// SameBody reports whether two renderings are equal apart from the first (timestamp) line.
func SameBody(a, b []byte) bool { return bytes.Equal(StripHeaderLine(a), StripHeaderLine(b)) }

// SHA256Hex is the lower-case hex sha256 of b, the form state.llama.ini_sha256 holds.
func SHA256Hex(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// hashModel is what one rendered model contributes to inputs_sha256: the catalog fields the table
// maps (llama.env is not in the INI, so it is not hashed) plus the chosen root and the aliases.
type hashModel struct {
	ID      string
	Root    string
	Roles   []string
	Llama   *catalog.Llama
	Files   []hashFile
	Aliases []string
}

type hashFile struct{ Kind, Name string }

// HashInput is what InputsHash covers: the inputs of a rendering (llama-router.md section 4.2
// step 2). The profile and the overrides act through the effective set, so the set's models are
// hashed rather than the whole profile: an edit that changes nothing in the file changes nothing
// in the hash.
type HashInput struct {
	Node           string
	Profile        string
	CatalogVersion string
	AddModels      []string
	RemoveModels   []string
	Default        string
	Entries        []Entry
	Aliases        map[string][]string
}

// InputsHash is inputs_sha256: the sha256 of the canonical JSON (fixed field order, sorted map
// keys, sorted lists, no HTML escaping) of every input of the rendering.
func InputsHash(in HashInput) string {
	doc := struct {
		Renderer int
		Node     string
		Profile  string
		Catalog  string
		Add      []string
		Remove   []string
		Default  string
		Models   []hashModel
	}{
		Renderer: RendererVersion, Node: in.Node, Profile: in.Profile, Catalog: in.CatalogVersion,
		Add: sortedCopy(in.AddModels), Remove: sortedCopy(in.RemoveModels), Default: in.Default,
	}
	for _, e := range in.Entries {
		m := hashModel{ID: e.Model.ID, Root: e.Root, Roles: e.Model.Roles, Aliases: sortedCopy(in.Aliases[e.Model.ID])}
		if e.Model.Llama != nil {
			l := *e.Model.Llama
			l.Env = nil
			m.Llama = &l
		}
		for _, f := range e.Model.Files {
			m.Files = append(m.Files, hashFile{f.Kind, f.Name})
		}
		// The order of the catalog's file list does not reach the file.
		sort.Slice(m.Files, func(a, b int) bool {
			if m.Files[a].Kind != m.Files[b].Kind {
				return m.Files[a].Kind < m.Files[b].Kind
			}
			return m.Files[a].Name < m.Files[b].Name
		})
		doc.Models = append(doc.Models, m)
	}
	sort.Slice(doc.Models, func(a, b int) bool { return doc.Models[a].ID < doc.Models[b].ID })
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(doc) // plain data: cannot fail
	return SHA256Hex(buf.Bytes())
}

func sortedCopy(in []string) []string {
	out := append([]string(nil), in...)
	sort.Strings(out)
	return out
}
